select row_number() over (order by id) as a, rank() over (order by n) as b, dense_rank() over (order by n) as c, count(*) over () as d, sum(small) over () as e, lag(n) over (order by id) as f, lead(name) over (order by id) as g, first_value(name) over (order by id) as h, last_value(n) over (order by id) as i, nth_value(n, 2) over (order by id) as j, ntile(2) over (order by id) as k, percent_rank() over (order by id) as l, cume_dist() over (order by id) as m, max(n) over (partition by small) as o, lag(n, 1, 0) over (order by id) as p, min(name) over () as q, avg(small) over () as r, count(maybe_n) over () as s, sum(small) over (order by id rows between 1 preceding and 1 preceding) as u, first_value(n) over (order by id rows between 1 following and 2 following) as v, bit_or(small) over () as w, json_arrayagg(n) over () as x from t where n between -1 and 2
